// One row in Eventos per milestone. Same format for every Lumière flow (feeds the office and P36 reports).
// Una fila en Eventos por hito. Mismo formato para todos los flujos de Lumière (alimenta la oficina y los reportes de P36).
// Columns / Columnas: evento_id, fecha, tipo, proyecto, lead_id, ref_id, detalle
const TIPOS = ['lead_llega', 'cita_agendada', 'toque_enviado', 'recordatorio_confirmado', 'resena', 'clienta_vuelve', 'escalamiento', 'error'];
const PROYECTOS = ['P30', 'P31', 'P32', 'P33', 'P34', 'P35', 'P36'];
const rand = () => Math.random().toString(36).slice(2, 7).toUpperCase();
const fecha = $now.setZone('America/Phoenix').toFormat('yyyy-MM-dd HH:mm:ss');
const out = [];
for (const item of $input.all()) {
  const e = item.json || {};
  const tipo = String(e.tipo || '').trim();
  const proyecto = String(e.proyecto || '').trim().toUpperCase();
  if (!TIPOS.includes(tipo) || !PROYECTOS.includes(proyecto)) continue;   // unknown event -> ignored, never breaks the caller
  const detalle = String(e.detalle || '').replace(/\s+/g, ' ').trim().slice(0, 200);
  out.push({ json: { row: ['EVT-' + fecha.slice(0, 10).replace(/-/g, '') + '-' + rand(), fecha, tipo, proyecto,
    String(e.lead_id || ''), String(e.ref_id || ''), detalle] } });
}
return out;

// What the caller gets back (callers do not wait for it: fire and forget).
// Lo que recibe quien llama (no lo espera: dispara y sigue).
const rows = $('Build Event Row').all();
return $input.all().map((item, i) => ({ json: {
  ok: !item.json.error,
  evento_id: rows[i] ? rows[i].json.row[0] : '',
  tipo: rows[i] ? rows[i].json.row[2] : '',
  error: item.json.error ? String(item.json.error.message || item.json.error) : ''
} }));
